package diplomacy.client;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Texture;
import com.badlogic.gdx.graphics.g2d.SpriteBatch;
import com.badlogic.gdx.graphics.glutils.ShaderProgram;
import com.badlogic.gdx.utils.Disposable;
import diplomacy.sim.Battle;
import java.util.IdentityHashMap;
import java.util.Map;

/**
 * Full-resolution source-art GL2/ES2 hull shader. A fourth optional sampler\n * encodes localized damage coefficients, NEVER replacement ship imagery.
 * Source-derived normal and emissive maps are generated by the ASSET BUILD,
 * uploaded once per unique source texture and never allocated in battle loops.
 */
final class ShipSurfaceLighting implements Disposable {
    static final String VERTEX =
        "attribute vec4 a_position;\n"+
        "attribute vec4 a_color;\n"+
        "attribute vec2 a_texCoord0;\n"+
        "uniform mat4 u_projTrans;\n"+
        "varying vec4 v_color;\n"+
        "varying vec2 v_uv;\n"+
        "varying vec2 v_world;\n"+
        "void main(){v_color=a_color;v_uv=a_texCoord0;v_world=a_position.xy;gl_Position=u_projTrans*a_position;}\n";
    static final String FRAGMENT =
        "#ifdef GL_ES\nprecision mediump float;\n#endif\n"+
        "varying vec4 v_color;\n"+
        "varying vec2 v_uv;\n"+
        "varying vec2 v_world;\n"+
        "uniform float u_detail;\n"+
        "uniform vec4 u_light0;\n"+
        "uniform vec4 u_light1;\n"+
        "uniform vec3 u_color0;\n"+
        "uniform vec3 u_color1;\n"+
        "uniform sampler2D u_texture;\n"+
        "uniform sampler2D u_normal;\n"+
        "uniform sampler2D u_emission;\n"+
        "uniform sampler2D u_damage;\n"+
        "uniform float u_hasDamage;\n"+
        "vec3 localLight(vec4 spot,vec3 tint,vec3 normal,vec2 axis){\n"+
        " if(spot.w<=0.0)return vec3(0.0);\n"+
        " vec2 ray=spot.xy-v_world;\n"+
        " float distance=length(ray);\n"+
        " float attenuation=clamp(1.0-distance/max(1.0,spot.z),0.0,1.0);\n"+
        " if(attenuation<=0.0)return vec3(0.0);\n"+
        " vec2 direction=ray/max(0.01,distance);\n"+
        " vec2 local=vec2(dot(direction,axis),-direction.x*axis.y+direction.y*axis.x);\n"+
        " float facing=max(dot(normal,normalize(vec3(local,0.85))),0.0);\n"+
        " return tint*(0.12+0.88*facing)*spot.w*attenuation*attenuation*attenuation;\n"+
        "}\n"+
        "void main(){\n"+
        " vec4 albedo=texture2D(u_texture,v_uv);\n"+
        " albedo.a*=v_color.a;\n"+
        " vec3 residualHeat=vec3(0.0);\n"+
        " if(u_hasDamage>0.5){\n"+
        "  vec4 peel=texture2D(u_damage,v_uv);\n"+
        "  albedo.a*=peel.a;\n"+
        "  albedo.rgb*=1.0-0.54*peel.r;\n"+
        "  // Feather B-channel material classification across bilinear texels.\n"+
        "  // A hard laser/metal branch painted orange and chrome contours around\n"+
        "  // the 96px oxide extent. Cold kinetic metal has G=0; hot plasma cannot\n"+
        "  // reach the reserved B>=0.64 tag range. Neither is misclassified.\n"+
        "  float oxideMix=smoothstep(0.56,0.72,peel.b)*smoothstep(0.035,0.10,peel.g);\n"+
        "  float thermal=peel.g*(1.0-oxideMix);\n"+
        "  albedo.rgb=mix(albedo.rgb,vec3(1.0,0.48,0.18),thermal*0.48);\n"+
        "  float sourceLum=dot(albedo.rgb,vec3(0.2126,0.7152,0.0722));\n"+
        "  float metalBoost=1.0-smoothstep(0.12,0.60,sourceLum);\n"+
        "  float coolMetal=1.0-smoothstep(0.005,0.08,peel.g);\n"+
        "  float metalStrength=clamp(peel.b/0.56,0.0,1.0)*mix(0.82,1.0,metalBoost)*coolMetal*(1.0-oxideMix);\n"+
        "  albedo.rgb=mix(albedo.rgb,vec3(0.90,0.94,1.0),metalStrength);\n"+
        "  float moltenLip=clamp(peel.b/0.56,0.0,1.0)*smoothstep(0.11,0.38,thermal);\n"+
        "  albedo.rgb=mix(albedo.rgb,vec3(1.0,0.72,0.33),moltenLip*0.43);\n"+
        "  residualHeat=vec3(0.32,0.105,0.018)*thermal*thermal;\n"+
        "  // Laser discoloration is wider than plasma heat, but not a luminous\n"+
        "  // outer circle. Oxide phase bends bronze -> violet -> blue on surviving\n"+
        "  // plating; the narrow scored core may carry localized incandescent light.\n"+
        "  float phase=peel.g;\n"+
        "  vec3 oxide=mix(vec3(0.79,0.60,0.31),vec3(0.64,0.39,0.29),smoothstep(0.07,0.29,phase));\n"+
        "  oxide=mix(oxide,vec3(0.49,0.35,0.66),smoothstep(0.30,0.57,phase));\n"+
        "  oxide=mix(oxide,vec3(0.31,0.52,0.81),smoothstep(0.59,0.88,phase));\n"+
        "  float temper=clamp((peel.b-0.56)/0.44,0.0,1.0);\n"+
        "  // Cooled violet/blue plating should be visible outside the warmer\n"+
        "  // score. Previously B opacity falloff suppressed this broad band\n"+
        "  // and left an orange crater. Color strength stays tied to oxide.\n"+
        "  float coolPhase=smoothstep(0.40,0.69,phase);\n"+
        "  float anneal=oxideMix*max(temper,0.46*coolPhase);\n"+
        "  float luma=dot(albedo.rgb,vec3(0.2126,0.7152,0.0722));\n"+
        "  albedo.rgb=mix(albedo.rgb,oxide,anneal*(0.39+0.15*smoothstep(0.06,0.70,luma)));\n"+
        "  float laserLip=smoothstep(0.86,0.97,peel.b)*smoothstep(0.04,0.35,peel.a)*oxideMix;\n"+
        "  residualHeat+=vec3(0.32,0.115,0.025)*laserLip*0.72;\n"+
        " }\n"+
        " if(albedo.a<0.004){gl_FragColor=vec4(0.0);return;}\n"+
        " if(u_detail<0.01){gl_FragColor=vec4(min(albedo.rgb+residualHeat,vec3(1.0)),albedo.a);return;}\n"+
        " vec3 n=normalize(texture2D(u_normal,v_uv).rgb*2.0-1.0);\n"+
        " vec2 axis=normalize(v_color.rg*2.0-1.0);\n"+
        " vec3 key=normalize(vec3(-0.52*axis.x+0.45*axis.y,\n"+
        "                          0.52*axis.y+0.45*axis.x,0.75));\n"+
        " float diffuse=max(dot(n,key),0.0);\n"+
        " float glint=pow(max(dot(reflect(-key,n),vec3(0.0,0.0,1.0)),0.0),24.0);\n"+
        " float rim=pow(clamp(1.0-n.z,0.0,1.0),2.0);\n"+
        " vec3 emitted=texture2D(u_emission,v_uv).rgb*v_color.b;\n"+
        " vec3 lit=albedo.rgb*(0.67+0.40*diffuse)+vec3(0.19)*glint;\n"+
        " lit+=vec3(0.055,0.10,0.13)*rim+emitted*0.95;\n"+
        " // Combined dynamic weapon lighting may never flood intact armor.\n"+
        " vec3 strikeLight=(localLight(u_light0,u_color0,n,axis)+\n"+
        "                   localLight(u_light1,u_color1,n,axis))*u_detail;\n"+
        " float peak=max(strikeLight.r,max(strikeLight.g,strikeLight.b));\n"+
        " strikeLight*=min(1.0,0.12/max(peak,0.0001));\n"+
        " lit+=strikeLight;\n"+
        " lit=mix(albedo.rgb,lit,u_detail)+residualHeat;\n"+
        " gl_FragColor=vec4(min(lit,vec3(1.0)),albedo.a);\n"+
        "}\n";

    /** One additional texture read only for damaged ships at tactical LOD.
     * Intact vessels retain the original cheap flat rendering path. */
    static final String FLAT_DAMAGE_FRAGMENT =
        "#ifdef GL_ES\nprecision mediump float;\n#endif\n"+
        "varying vec4 v_color;\n"+
        "varying vec2 v_uv;\n"+
        "uniform sampler2D u_texture;\n"+
        "uniform sampler2D u_damage;\n"+
        "uniform float u_underlayPass;\n"+
        "void main(){\n"+
        " vec4 albedo=texture2D(u_texture,v_uv);\n"+
        " vec4 peel=texture2D(u_damage,v_uv);\n"+
        " if(u_underlayPass>0.5){\n"+
        "  // Exact inverse of the armor alpha: no second transparent hull\n"+
        "  // silhouette and therefore no doubled exterior antialiasing.\n"+
        "  albedo.a*=(1.0-peel.a)*v_color.a;\n"+
        " }else{\n"+
        "  albedo.rgb*=1.0-0.54*peel.r;\n"+
        "  albedo.a*=peel.a*v_color.a;\n"+
        " }\n"+
        " gl_FragColor=albedo;\n"+
        "}\n";
    private static final class Pair {
        final Texture normal,emissive;
        Pair(Texture normal,Texture emissive){this.normal=normal;this.emissive=emissive;}
        void dispose(){normal.dispose();emissive.dispose();}
    }
    private final Map<Texture,Pair> pairs=new IdentityHashMap<>();
    private final ShaderProgram shader;
    private ShaderProgram flatDamageShader;
    private boolean flatDamageShaderUnavailable;
    private boolean underlayPass;
    private final ShipLightProbes probes=new ShipLightProbes();
    private Texture active;
    private Texture activeDamage;
    private boolean started;
    private boolean flat;
    private int binds;

    ShipSurfaceLighting(){
        ShaderProgram.pedantic=false;
        ShaderProgram compiled=new ShaderProgram(VERTEX,FRAGMENT);
        if(!compiled.isCompiled()){
            String diagnostic=compiled.getLog();
            compiled.dispose();
            throw new IllegalStateException("Ship normal/emissive GL2 shader could not compile: "+diagnostic);
        }
        shader=compiled;
    }
    static String normalPath(String path){return surfacePath(path,"_n.png");}
    static String emissivePath(String path){return surfacePath(path,"_e.png");}
    private static String surfacePath(String path,String suffix){
        if(path==null||!path.startsWith("ships/")||!path.endsWith(".png"))
            throw new IllegalArgumentException("Invalid approved ship material path: "+path);
        return path.substring(0,path.length()-4)+suffix;
    }
    void prepare(Texture original,String path){
        if(pairs.containsKey(original))return;
        String n=normalPath(path),e=emissivePath(path);
        if(!Gdx.files.internal(n).exists()||!Gdx.files.internal(e).exists())
            throw new IllegalStateException("Required authored-source material maps missing: "+n+" / "+e);
        // Material layers must use the same LOD filtering as the original
        // authored hull image; trilinear filtering reduces distant shimmer.
        Texture normal=ShipTextureSampling.load(n);
        Texture emissive=null;
        try {
            emissive=ShipTextureSampling.load(e);
            if(normal.getWidth()!=emissive.getWidth()
                    ||normal.getHeight()!=emissive.getHeight()
                    ||normal.getWidth()>original.getWidth() || normal.getHeight()>original.getHeight()
                    ||Math.abs(normal.getWidth()/(float)original.getWidth()
                             -normal.getHeight()/(float)original.getHeight())>.015f)
                throw new IllegalStateException("Ship normal/emissive UV dimensions differ: "+path);
            pairs.put(original,new Pair(normal,emissive));
        }catch(RuntimeException failure){
            normal.dispose();if(emissive!=null)emissive.dispose();
            throw failure;
        }
    }
    /**
     * Encode per-sprite rotation in the existing packed vertex color channels.
     * The material shader decodes it as world-light direction, not a tint.
     * No per-vessel uniform upload, shader rebind, or forced draw-call flush.
     */
    static void heading(SpriteBatch batch,float spriteRotationDegrees){
        heading(batch,spriteRotationDegrees,1f);
    }
    static void heading(SpriteBatch batch,float spriteRotationDegrees,float integrity){
        heading(batch,spriteRotationDegrees,integrity,1f);
    }
    static void heading(SpriteBatch batch,float spriteRotationDegrees,float integrity,
                        float opacity){
        double theta=Math.toRadians(spriteRotationDegrees);
        batch.setColor((float)(.5+.5*Math.cos(theta)),
                       (float)(.5+.5*Math.sin(theta)),
                       Math.max(0f,Math.min(1f,integrity)),
                       Math.max(0f,Math.min(1f,opacity)));
    }
    /** Strategic LOD uses the actual original art path, avoiding all material
     * texture binds and the three-sampler shader for distant fleet views. */
    static boolean flatAt(CombatViewBounds view){
        return ShipLightProbes.detail(view)<.01f;
    }
    void color(SpriteBatch batch,float rotation,float integrity){
        color(batch,rotation,integrity,1f);
    }
    void color(SpriteBatch batch,float rotation,float integrity,float opacity){
        if(flat)batch.setColor(1f,1f,1f,opacity);
        else heading(batch,rotation,integrity,opacity);
    }
    void color(SpriteBatch batch,float rotation){color(batch,rotation,1f);}
    void begin(SpriteBatch batch){begin(batch,null,null);}
    void begin(SpriteBatch batch,Battle battle,CombatViewBounds view){
        active=null;activeDamage=null;underlayPass=false;binds=0;started=true;
        flat=flatAt(view);
        if(flat){
            batch.setShader(null);
            batch.begin();
            return;
        }
        probes.select(battle,view);
        batch.setShader(shader);
        batch.begin();
        shader.setUniformi("u_normal",1);
        shader.setUniformi("u_emission",2);
        shader.setUniformi("u_damage",3);
        shader.setUniformf("u_hasDamage",0f);
        shader.setUniformf("u_detail",ShipLightProbes.detail(view));
        shader.setUniformf("u_light0",probes.x(0),probes.y(0),probes.radius(0),probes.power(0));
        shader.setUniformf("u_light1",probes.x(1),probes.y(1),probes.radius(1),probes.power(1));
        shader.setUniformf("u_color0",probes.red(0),probes.green(0),probes.blue(0));
        shader.setUniformf("u_color1",probes.red(1),probes.green(1),probes.blue(1));
    }
    private ShaderProgram flatDamageShader(){
        if(flatDamageShader!=null)return flatDamageShader;
        if(flatDamageShaderUnavailable)return null;
        ShaderProgram program=new ShaderProgram(VERTEX,FLAT_DAMAGE_FRAGMENT);
        if(!program.isCompiled()){
            String log=program.getLog();
            program.dispose();
            flatDamageShaderUnavailable=true;
            // Optional visual path must NEVER prevent battle launch.
            if(Gdx.app!=null)Gdx.app.error("ARMOR","Tactical damage shader unavailable: "+log);
            return null;
        }
        flatDamageShader=program;
        return program;
    }
    /**
     * Render structural metal ONLY where the mask removed upper plating.
     * The underlay is dark, unlit, UV-matched source art: it never inherits
     * the intact hull's emissive map and cannot double exterior-edge alpha.
     * Failure of this OPTIONAL cosmetic shader never aborts the battle.
     */
    boolean underlay(SpriteBatch batch,Texture mask){
        if(mask==null)return false;
        ShaderProgram simple=flatDamageShader();
        if(simple==null)return false;
        if(batch.getShader()!=simple){
            batch.setShader(simple);
            simple.setUniformi("u_damage",1);
            activeDamage=null;
        }
        batch.flush();
        if(activeDamage!=mask){
            mask.bind(1);
            Gdx.gl.glActiveTexture(GL20.GL_TEXTURE0);
            activeDamage=mask;
        }
        simple.setUniformf("u_underlayPass",1f);
        underlayPass=true;
        active=null;
        return true;
    }
    /** In the hot draw loop: only flush when the *source sprite* changes. */
    void bind(SpriteBatch batch,Texture original){
        if(flat)return;
        Pair pair=pairs.get(original);
        if(pair==null)throw new IllegalStateException("Unprepared ship surface texture");
        if(batch.getShader()!=shader){
            batch.setShader(shader);
            shader.setUniformi("u_normal",1);
            shader.setUniformi("u_emission",2);
            shader.setUniformi("u_damage",3);
            shader.setUniformf("u_hasDamage",0f);
            active=null;activeDamage=null;
        }
        if(active==original)return;
        batch.flush();
        pair.normal.bind(1);
        pair.emissive.bind(2);
        Gdx.gl.glActiveTexture(GL20.GL_TEXTURE0);
        active=original;
        binds++;
    }
    /**
     * Binds one cached 192x288 per-ship peel mask; original full-resolution
     * albedo, normals, and emissive material stay bound as the source artwork.
     */
    void damage(SpriteBatch batch,Texture mask){
        if(flat){
            if(mask==null){
                if(batch.getShader()!=null)batch.setShader(null);
                activeDamage=null;
                return;
            }
            ShaderProgram simple=flatDamageShader();
            if(simple==null)return;
            if(batch.getShader()!=simple){
                batch.setShader(simple);
                simple.setUniformi("u_damage",1);
                activeDamage=null;
                underlayPass=false;
            }
            if(activeDamage!=mask||underlayPass){
                batch.flush();
                if(activeDamage!=mask){
                    mask.bind(1);
                    Gdx.gl.glActiveTexture(GL20.GL_TEXTURE0);
                    activeDamage=mask;
                }
                simple.setUniformf("u_underlayPass",0f);
                underlayPass=false;
            }
            return;
        }
        if(activeDamage==mask)return;
        batch.flush();
        if(mask!=null){
            mask.bind(3);
            Gdx.gl.glActiveTexture(GL20.GL_TEXTURE0);
        }
        shader.setUniformf("u_hasDamage",mask==null?0f:1f);
        activeDamage=mask;
    }
    /** Only truly unillustrated fallback craft should use the unlit path. */
    void unlit(SpriteBatch batch){
        if(batch.getShader()!=null)batch.setShader(null);
        active=null;activeDamage=null;
    }
    void end(SpriteBatch batch){
        if(!started)return;
        batch.end();
        batch.setShader(null);
        active=null;activeDamage=null;underlayPass=false;started=false;flat=false;
    }
    /** Release an inactive original and its GPU materials after a completed frame. */
    void forget(Texture original){
        Pair pair=pairs.remove(original);
        if(pair!=null)pair.dispose();
        if(active==original)active=null;
    }
    int materialCount(){return pairs.size();}
    int textureBindings(){return binds;}
    @Override public void dispose(){
        if(flatDamageShader!=null)flatDamageShader.dispose();
        for(Pair p:pairs.values())p.dispose();
        pairs.clear();
        shader.dispose();
    }
}
